/* ========================================
   COLOR SWATCHES
   ======================================== */
.color-swatches {
    display: flex;
    gap: 8px;
}

.color-swatch {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    border: 2px solid var(--card-border);
    cursor: pointer;
    transition: transform 0.2s;
}

.color-swatch:hover {
    transform: scale(1.15);
}

/* ========================================
   FORM ACTIONS
   ======================================== */
.form-actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 16px;
    padding-top: 20px;
    border-top: 1px solid var(--card-border);
}

.btn-secondary {
    background: transparent;
    border: 1px solid var(--card-border);
    color: var(--text-dim);
    padding: 10px 20px;
    border-radius: 20px;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.9rem;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    gap: 6px;
}

.btn-secondary:hover {
    border-color: var(--text-dim);
    color: var(--text-main);
}

.btn-primary {
    background: var(--accent-purple);
    border: none;
    color: white;
    padding: 10px 24px;
    border-radius: 20px;
    cursor: pointer;
    font-weight: 600;
    font-size: 0.9rem;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    gap: 6px;
}

.btn-primary:hover:not(:disabled):not(.saving) {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(155, 93, 229, 0.25);
}

.btn-primary:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ========================================
   DOT MATRIX PROGRESS ANIMATION
   ======================================== */
.btn-primary.saving {
    position: relative;
    overflow: hidden;
    background: linear-gradient(135deg, #1e1e2e 0%, #2a2a3a 100%);
    border: 1px solid rgba(155, 93, 229, 0.3);
    min-width: 180px;
    padding: 10px 20px;
}

.btn-primary.saving .btn-text {
    opacity: 0;
}

.btn-primary.saving .dot-matrix-container {
    display: flex;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.dot-matrix-container {
    display: none;
}

.dot-matrix {
    display: grid;
    grid-template-columns: repeat(10, 1fr);
    grid-template-rows: repeat(3, 1fr);
    gap: 3px;
    padding: 4px;
}

.dot {
    width: 6px;
    height: 6px;
    border-radius: 2px;
    background: rgba(155, 93, 229, 0.2);
    transition: all 0.15s ease;
}

.dot.active {
    background: linear-gradient(135deg, #00d4ff 0%, #9b5de5 100%);
    box-shadow: 0 0 6px rgba(0, 212, 255, 0.5);
}

.dot.complete {
    background: linear-gradient(135deg, #22c55e 0%, #4ade80 100%);
    box-shadow: 0 0 6px rgba(34, 197, 94, 0.5);
}

/* Wave animation for active dots */
@keyframes dotPulse {

    0%,
    100% {
        transform: scale(1);
        opacity: 1;
    }

    50% {
        transform: scale(1.2);
        opacity: 0.8;
    }
}

.dot.active {
    animation: dotPulse 0.5s ease infinite;
}

/* Success state */
.btn-primary.saved {
    background: linear-gradient(135deg, #22c55e 0%, #4ade80 100%);
    border: none;
}

.btn-primary.saved .dot-matrix-container {
    display: none;
}

.btn-primary.saved .btn-text {
    opacity: 1;
}

/* ========================================
   LOADING ANIMATION (Minimal)
   ======================================== */
/* ========================================
   LOADING ANIMATION (Minimal)
   ======================================== */
.analysis-loading {
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;
    width: 100%;
    margin: 0 auto;
    min-height: 320px;
    /* Match approximate height of upload zone */
}

.neural-loader {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.neural-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--accent-purple);
    opacity: 0.3;
    animation: dotBounce 1.2s ease-in-out infinite;
}

.neural-dot:nth-child(1) {
    animation-delay: 0s;
}

.neural-dot:nth-child(2) {
    animation-delay: 0.15s;
}

.neural-dot:nth-child(3) {
    animation-delay: 0.3s;
}

.neural-dot:nth-child(4) {
    animation-delay: 0.45s;
}

.neural-dot:nth-child(5) {
    animation-delay: 0.6s;
}

@keyframes dotBounce {

    0%,
    80%,
    100% {
        transform: scale(1);
        opacity: 0.3;
    }

    40% {
        transform: scale(1.3);
        opacity: 1;
    }
}

/* ========================================
   TOAST NOTIFICATIONS
   ======================================== */
.toast-container {
    position: fixed;
    bottom: 24px;
    right: 24px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    z-index: 1000;
}

.toast {
    padding: 14px 20px;
    background: #ffffff;
    /* Explicit white for Light Mode */
    border: 1px solid var(--card-border);
    border-radius: 10px;
    color: var(--text-main);
    font-family: var(--font-sans);
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 10px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
    animation: slideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    z-index: 1000;
}

[data-theme="dark"] .toast {
    background: #1e293b;
    /* Slate 800 for Dark Mode */
    border-color: rgba(255, 255, 255, 0.1);
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
}

.toast.success {
    border-left: 3px solid #22c55e;
}

.toast.success i {
    color: #22c55e;
}

.toast.error {
    border-left: 3px solid #ef4444;
}

.toast.error i {
    color: #ef4444;
}

.toast.is-dismissing {
    animation: slideIn 0.3s ease reverse;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateX(100%);
    }

    to {
        opacity: 1;
        transform: translateX(0);
    }
}

