}

/* ========================================
   BATCH OPERATIONS
   ======================================== */

/* Batch Actions Wrapper */
.batch-actions-wrapper {
    display: flex;
    gap: 8px;
    align-items: center;
}

.batch-menu-container {
    position: relative;
}

.batch-menu-trigger {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    color: var(--text-dim);
    cursor: pointer;
    transition: all 0.3s ease;
}

.batch-menu-trigger:hover {
    background: rgba(155, 93, 229, 0.1);
    border-color: rgba(155, 93, 229, 0.3);
    color: var(--accent-purple);
}

/* Batch Dropdown Menu */
.batch-dropdown-menu {
    position: absolute;
    top: calc(100% + 8px);
    right: 0;
    min-width: 160px;
    background: rgba(255, 255, 255, 0.55);
    backdrop-filter: blur(24px) saturate(180%);
    -webkit-backdrop-filter: blur(24px) saturate(180%);
    border: 1px solid rgba(155, 93, 229, 0.15);
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.12);
    border-radius: 12px;
    padding: 6px;
    z-index: 100;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transition: all 0.2s ease;
}

.batch-menu-container.open .batch-dropdown-menu,
.batch-dropdown-menu.open {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

[data-theme="dark"] .batch-dropdown-menu {
    background: rgba(30, 41, 59, 0.65);
    border-color: rgba(93, 159, 216, 0.2);
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}

.batch-menu-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    border-radius: 6px;
    color: var(--text-main);
    cursor: pointer;
    transition: background 0.2s ease;
    font-size: 0.9rem;
}

.batch-menu-container.is-busy .batch-dropdown-menu {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

.batch-menu-item.is-disabled,
.batch-menu-item[aria-disabled="true"] {
    opacity: 0.42;
    cursor: not-allowed;
    pointer-events: none;
    box-shadow: none;
    transform: none;
}

.batch-menu-item.is-pending {
    background: rgba(37, 99, 235, 0.14);
    box-shadow: inset 0 0 0 1px rgba(96, 165, 250, 0.26);
    cursor: progress;
}

.batch-menu-item.is-pending i {
    color: rgba(147, 197, 253, 0.98);
}

.batch-menu-container.is-busy .batch-menu-item:not(.is-pending) {
    opacity: 0.34;
    pointer-events: none;
}

/* Batch Menu Item Hover */
.batch-menu-item:hover {
    background: rgba(255, 255, 255, 0.08);
    transform: translateY(-0.5px);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    z-index: 1;
    position: relative;
    border-radius: 6px;
}

/* Light Mode Overrides for Batch Menu */
:root:not([data-theme="dark"]) .batch-menu-item:hover {
    background: #f1f5f9;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
    /* Light shadow */
}

.batch-menu-item.danger:hover {
    background: rgba(239, 68, 68, 0.12);
    color: #ef4444;
}

.batch-menu-item i {
    width: 16px;
    text-align: center;
    color: var(--text-dim);
}

.batch-menu-item:hover i {
    color: var(--accent-purple);
}

.batch-menu-item.danger:hover i {
    color: #ef4444;
}

.batch-menu-divider {
    height: 1px;
    background: rgba(255, 255, 255, 0.08);
    margin: 6px 0;
}

/* Selection Count Display */
.prompt-count .select-count {
    color: var(--accent-purple);
}

/* Batch Action Buttons */

.batch-btn {
    width: 32px;
    /* Reduced from 40px */
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 8px;
    /* Reduced from 10px */
    color: var(--text-dim);
    cursor: pointer;
    transition: all 0.3s ease;
    font-size: 0.85rem;
    /* Smaller icon */
}

.batch-btn:hover:not(:disabled) {
    background: rgba(155, 93, 229, 0.1);
    border-color: rgba(155, 93, 229, 0.3);
    color: var(--accent-purple);
}

.batch-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.batch-btn.active {
    background: rgba(155, 93, 229, 0.15);
    border-color: rgba(155, 93, 229, 0.4);
    color: var(--accent-purple);
}

[data-theme="dark"] .batch-btn:hover:not(:disabled) {
    background: rgba(93, 159, 216, 0.1);
    border-color: rgba(93, 159, 216, 0.3);
}

[data-theme="dark"] .batch-btn.active {
    background: rgba(93, 159, 216, 0.15);
    border-color: rgba(93, 159, 216, 0.4);
}

.batch-btn.danger:hover:not(:disabled) {
    background: rgba(239, 68, 68, 0.1);
    border-color: rgba(239, 68, 68, 0.3);
    color: #ef4444;
}

/* Selection Mode Cards */
.select-mode .admin-card {
    cursor: pointer;
}

/* In select mode, hide the normal hover actions overlay */
.select-mode .admin-card .admin-card-actions {
    display: none !important;
}

.select-mode .admin-card .admin-card-hover-actions.left {
    left: 52px;
}

.admin-card .select-checkbox {
    position: absolute;
    top: 12px;
    left: 12px;
    width: 24px;
    height: 24px;
    background: rgba(0, 0, 0, 0.5);
    border: 2px solid rgba(255, 255, 255, 0.4);
    border-radius: 6px;
    display: none;
    align-items: center;
    justify-content: center;
    color: transparent;
    /* Hide check icon by default */
    font-size: 12px;
    z-index: 10;
    transition: all 0.2s ease;
}

.select-mode .admin-card .select-checkbox {
    display: flex;
}

/* Show check icon only when selected */
.admin-card.selected .select-checkbox {
    background: var(--accent-purple);
    border-color: var(--accent-purple);
    color: white;
    /* Show check icon */
}

.admin-card.selected {
    border-color: var(--accent-purple);
    box-shadow: 0 0 0 2px rgba(155, 93, 229, 0.3);
}

.admin-card.is-batch-pending,
.admin-card.is-batch-pending:hover {
    transform: none;
    border-color: rgba(96, 165, 250, 0.42);
    box-shadow: 0 0 0 2px rgba(96, 165, 250, 0.18), 0 18px 42px rgba(5, 10, 24, 0.22);
}

.admin-card.is-batch-pending .admin-card-image {
    filter: saturate(0.82) brightness(0.9);
}

.admin-card.is-batch-pending .select-checkbox {
    background: var(--accent-purple);
    border-color: var(--accent-purple);
    color: white;
}

.admin-card--hidden-by-search {
    display: none !important;
}

.admin-card--hidden-by-pagination {
    display: none !important;
}

.admin-card.is-removing {
    transition: opacity 0.3s ease, transform 0.3s ease;
    opacity: 0;
    transform: scale(0.9);
}

/* Batch Edit Bar - Floating Pill Design */
.batch-edit-bar {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: linear-gradient(135deg, rgba(155, 93, 229, 0.15) 0%, rgba(155, 93, 229, 0.08) 100%);
    border: 1px solid rgba(155, 93, 229, 0.25);
    border-radius: 24px;
    padding: 6px 6px 6px 16px;
    margin: 0 auto 20px;
    grid-column: 1 / -1;
    box-shadow: 0 4px 20px rgba(155, 93, 229, 0.1);
}

[data-theme="dark"] .batch-edit-bar {
    background: linear-gradient(135deg, rgba(93, 159, 216, 0.15) 0%, rgba(93, 159, 216, 0.08) 100%);
    border-color: rgba(93, 159, 216, 0.25);
    box-shadow: 0 4px 20px rgba(93, 159, 216, 0.1);
}

.batch-edit-label {
    font-size: 0.8rem;
    color: var(--accent-purple);
    font-weight: 500;
    letter-spacing: 0.02em;
}

.batch-edit-dropdown {
    position: relative;
}

.batch-edit-current {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(107, 158, 206, 0.15);
    border: none;
    border-radius: 20px;
    padding: 6px 12px;
    color: var(--text-main);
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 0.9rem;
}

[data-theme="dark"] .batch-edit-current {
    background: rgba(93, 159, 216, 0.2);
}

[data-theme="dark"] .batch-edit-current:hover {
    background: rgba(93, 159, 216, 0.3);
}

.batch-edit-current:hover {
    background: rgba(107, 158, 206, 0.25);
}

.batch-edit-current .current-title {
    max-width: 150px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.batch-edit-current .current-index {
    color: rgba(255, 255, 255, 0.6);
    font-size: 0.8rem;
}

.batch-edit-current i {
    color: rgba(255, 255, 255, 0.6);
    font-size: 0.7rem;
    transition: transform 0.2s ease;
}

.batch-edit-dropdown.open .batch-edit-current i {
    transform: rotate(180deg);
}

.batch-edit-menu {
    position: absolute;
    top: calc(100% + 8px);
    left: 50%;
    transform: translateX(-50%) translateY(-10px);
    min-width: 280px;
    background: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(107, 158, 206, 0.25);
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.15);
    border-radius: 12px;
    padding: 8px;
    max-height: 320px;
    overflow-y: auto;
    z-index: 100;
    opacity: 0;
    visibility: hidden;
    transition: all 0.2s ease;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.batch-edit-dropdown.open .batch-edit-menu {
    opacity: 1;
    visibility: visible;
    transform: translateX(-50%) translateY(0);
}

[data-theme="dark"] .batch-edit-menu {
    background: rgba(30, 41, 59, 0.75);
    border-color: rgba(93, 159, 216, 0.25);
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
}

.batch-edit-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    border-radius: 8px;
    color: var(--text-main);
    cursor: pointer;
    transition: background 0.2s ease;
    white-space: nowrap;
}

.batch-edit-item:hover {
    background: rgba(107, 158, 206, 0.12);
}

.batch-edit-item.active {
    background: transparent !important;
    color: var(--accent-purple);
    font-weight: 500;
}

.batch-edit-item .check-icon {
    width: 20px;
    color: var(--accent-purple);
}

.batch-edit-close {
    background: rgba(255, 255, 255, 0.1);
    border: none;
    color: var(--text-dim);
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 0.75rem;
}

.batch-edit-close:hover {
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
}

/* Modal Overlay */
.batch-modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(8px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity 0.28s ease, visibility 0.28s ease;
}

.batch-modal-overlay.active {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
}

.batch-modal {
    background: rgba(20, 25, 45, 0.95);
    backdrop-filter: blur(20px);
    border: 1px solid rgba(155, 93, 229, 0.25);
    border-radius: 16px;
    padding: 28px;
    width: 90%;
    max-width: 420px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    opacity: 0;
    transform: translateY(22px) scale(0.97);
    transition: opacity 0.28s ease, transform 0.32s cubic-bezier(0.16, 1, 0.3, 1);
}

.batch-modal-overlay.active .batch-modal {
    opacity: 1;
    transform: translateY(0) scale(1);
}

.batch-modal-title {
    font-family: var(--font-serif);
    font-size: 1.3rem;
    font-weight: 400;
    color: var(--text-main);
    margin-bottom: 20px;
    text-align: center;
}

.batch-modal-body {
    margin-bottom: 24px;
}

.batch-current-item {
    color: var(--text-main);
    font-size: 0.95rem;
    margin-bottom: 16px;
    text-align: center;
}

.batch-progress-bar {
    background: rgba(255, 255, 255, 0.05);
    border-radius: 10px;
    height: 12px;
    overflow: hidden;
    margin-bottom: 12px;
}

.batch-progress-fill {
    appearance: none;
    -webkit-appearance: none;
    height: 100%;
    background: linear-gradient(90deg, var(--accent-purple), #00d4ff);
    border-radius: 10px;
    width: 100%;
    overflow: hidden;
    display: block;
    border: none;
}

.batch-progress-fill::-webkit-progress-bar {
    background: transparent;
    border-radius: 10px;
}

.batch-progress-fill::-webkit-progress-value {
    background: linear-gradient(90deg, var(--accent-purple), #00d4ff);
    border-radius: 10px;
}

.batch-progress-fill::-moz-progress-bar {
    background: linear-gradient(90deg, var(--accent-purple), #00d4ff);
    border-radius: 10px;
}

.batch-progress-text {
    text-align: center;
    color: var(--text-dim);
    font-size: 0.9rem;
    margin-bottom: 8px;
}

.batch-time-remaining {
    text-align: center;
    color: var(--text-dim);
    font-size: 0.85rem;
}

.batch-modal-actions {
    display: flex;
    justify-content: center;
    gap: 12px;
}

.btn-danger {
    background: #ef4444;
    border: none;
    color: white;
    padding: 10px 24px;
    border-radius: 20px;
    cursor: pointer;
    font-weight: 600;
    font-size: 0.9rem;
    transition: background 0.2s;
    display: flex;
    align-items: center;
    gap: 6px;
}

.btn-danger:hover {
    background: #dc2626;
}

.confirm-modal .warn-text {
    color: #ef4444;
    font-size: 0.85rem;
    text-align: center;
    margin-top: 8px;
}

/* Lightbox */
.lightbox-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.9);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 2000;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity 0.28s ease, visibility 0.28s ease;
}

.lightbox-overlay.active {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
}

.lightbox-image {
    max-width: 90%;
    max-height: 90vh;
    object-fit: contain;
    border-radius: 8px;
    opacity: 0;
    transform: scale(0.97);
    transition: opacity 0.28s ease, transform 0.32s cubic-bezier(0.16, 1, 0.3, 1);
}

.lightbox-overlay.active .lightbox-image {
    opacity: 1;
    transform: scale(1);
}

.lightbox-close {
    position: absolute;
    top: 20px;
    right: 20px;
    background: rgba(255, 255, 255, 0.1);
    border: none;
    color: white;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1.2rem;
    transition: background 0.2s ease;
}

.lightbox-close:hover {
    background: rgba(255, 255, 255, 0.2);
}

/* Crop Modal */
.crop-modal {
    max-width: 700px;
    width: 90vw;
}

.crop-aspect-buttons {
    display: flex;
    gap: 8px;
    margin-bottom: 16px;
    flex-wrap: wrap;
    justify-content: center;
}

.crop-aspect-btn {
    padding: 8px 16px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.05);
    color: var(--text-dim);
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 0.85rem;
}

.crop-aspect-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.3);
}

.crop-aspect-btn.active {
    background: var(--accent-color);
    border-color: var(--accent-color);
    color: white;
}

.crop-container {
    background: rgba(0, 0, 0, 0.5);
    border-radius: 8px;
    overflow: hidden;
    margin-bottom: 20px;
    max-height: 500px;
    min-height: 300px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.crop-container img {
    max-width: 100%;
    display: block;
}

/* Cropper.js overrides for dark theme */
.cropper-view-box,
.cropper-face {
    border-radius: 0;
}

.cropper-line {
    background-color: var(--accent-color);
}

.cropper-point {
    background-color: var(--accent-color);
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

