}

.admin-skeleton-w-70 {
    width: 70%;
}

.admin-skeleton-w-60 {
    width: 60%;
}

.admin-skeleton-w-50 {
    width: 50%;
}

.admin-skeleton-w-40 {
    width: 40%;
}

.admin-skeleton-w-30 {
