    background: rgba(0, 0, 0, 0.8);
    color: #fff;
}

/* Row Styles - Clean, no green border */
.user-row {
    cursor: pointer;
    transition: background 0.2s ease, box-shadow 0.2s ease;
    position: relative;
    border-radius: 8px;
}

/* Rounded corners on cells */
.user-row td:first-child {
    border-top-left-radius: 8px;
    border-bottom-left-radius: 8px;
}

.user-row td:last-child {
    border-top-right-radius: 8px;
    border-bottom-right-radius: 8px;
}

/* Hover - subtle lift */
.user-row:hover {
    background: rgba(255, 255, 255, 0.04);
    transform: translateY(-0.5px);
    box-shadow: 0 3px 12px rgba(0, 0, 0, 0.08);
}

.user-row:hover td {
    border-bottom-color: transparent;
}

[data-theme="dark"] .user-row:hover {
    background: rgba(255, 255, 255, 0.03);
}

/* ========================================
   BATCH SELECTION STYLES
   ======================================== */

/* Checkbox Column */
.checkbox-col {
    width: 50px;
    min-width: 50px;
    max-width: 50px;
    text-align: center;
    padding: 12px 16px !important;
    vertical-align: middle;
}

.checkbox-col .custom-checkbox {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto;
}

/* Custom Checkbox Styling to match design */
.custom-checkbox {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    position: relative;
    width: 16px;
    height: 16px;
    cursor: pointer;
    vertical-align: middle;
}

/* Hide default input */
.custom-checkbox input {
    position: absolute;
    opacity: 0;
    cursor: pointer;
    height: 0;
    width: 0;
}

/* Custom checkmark box */
.checkmark {
    position: absolute;
    top: 0;
    left: 0;
    height: 16px;
    width: 16px;
    background-color: transparent;
    border: 1.5px solid #cbd5e1;
    border-radius: 4px;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

[data-theme="dark"] .checkmark {
    border-color: rgba(255, 255, 255, 0.3);
}

/* Hover effect */
.custom-checkbox:hover input~.checkmark {
    border-color: #6366f1;
    /* Indigo hover */
}

/* Checked state */
.custom-checkbox input:checked~.checkmark {
    background-color: #5b9bd5;
    /* Match the lighter blue from screenshot */
    border-color: #5b9bd5;
    box-shadow: none;
    /* Removed shadow as requested */
}

/* Checkmark icon (hidden by default) */
.checkmark:after {
    content: "";
    position: absolute;
    display: none;
}

/* Show checkmark when checked */
.custom-checkbox input:checked~.checkmark:after {
    display: block;
}

/* Draw the checkmark */
.checkmark:after {
    left: 4px;
    top: 1px;
    width: 4px;
    height: 8px;
    border: solid white;
    border-width: 0 2px 2px 0;
    transform: rotate(45deg);
}

/* Selected Row Highlight - No Blue Border */
.user-row.selected {
    background: rgba(91, 155, 213, 0.08) !important;
    /* Matching light blue bg */
}

.user-row.selected td:first-child {
    border-left: none;
    /* Removed blue indicator */
}

[data-theme="dark"] .user-row.selected {
    background: rgba(59, 130, 246, 0.15) !important;
}

/* ========================================
   BATCH ACTION BAR (浮动岛设计)
   ======================================== */
.batch-action-bar {
    position: fixed;
    bottom: 32px;
    left: 50%;
    transform: translateX(-50%) translateY(200%);
    /* Initially hidden below */
    width: max-content;
    /* Allow it to grow to fit content */
    max-width: 90vw;
    /* Prevent screen overflow */
    padding: 12px 24px;
    background: rgba(255, 255, 255, 0.95);
    /* Slightly more opaque */
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.5);
    border-radius: 24px;
    box-shadow:
        0 20px 40px -10px rgba(0, 0, 0, 0.1),
        0 10px 20px -5px rgba(0, 0, 0, 0.05),
        0 0 0 1px rgba(0, 0, 0, 0.05);
    transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    z-index: 9999;
}

.batch-action-bar.active {
    transform: translateX(-50%) translateY(0);
}

[data-theme="dark"] .batch-action-bar {
    background: rgba(30, 41, 59, 0.85);
    border-color: rgba(255, 255, 255, 0.1);
    box-shadow:
        0 20px 40px -10px rgba(0, 0, 0, 0.3),
        0 0 0 1px rgba(255, 255, 255, 0.1);
}

.batch-bar-content {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
}

/* Left: Info Section */
.batch-info {
    display: flex;
    align-items: center;
    gap: 12px;
    color: #1e293b;
    font-size: 0.95rem;
    font-weight: 500;
    white-space: nowrap;
    padding-right: 24px;
    border-right: 1px solid rgba(0, 0, 0, 0.08);
    flex-shrink: 0;
    /* Prevent shrinking */
}

.batch-info i {
    font-size: 1.2rem;
    color: #3b82f6;
}

[data-theme="dark"] .batch-info {
    color: #e2e8f0;
    border-right-color: rgba(255, 255, 255, 0.15);
}

/* Right: Actions */
.batch-actions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: nowrap;
    /* Prevent wrapping */
}

/* Action Buttons */
.batch-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 18px;
    border: none;
    border-radius: 12px;
    background: transparent;
    color: #64748b;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    white-space: nowrap;
    /* Prevent text wrapping */
    flex-shrink: 0;
    /* Prevent button shrinking */
}

.batch-btn i {
    font-size: 1.1rem;
    transition: transform 0.2s ease;
}

/* Hover States - Morphing backgrounds */
.batch-btn:hover {
    background: rgba(241, 245, 249, 0.8);
    color: #0f172a;
    transform: translateY(-2px);
}

/* Specific Button Colors on Hover */
.batch-btn:hover i {
    transform: scale(1.1);
}

/* Notification (Blue) */
.batch-btn[onclick*="Notification"]:hover {
    background: rgba(59, 130, 246, 0.1);
    color: #3b82f6;
}

/* Ban (Red) */
.batch-btn.danger {
    color: #64748b;
    /* Default grey */
}

.batch-btn.danger:hover {
    background: rgba(239, 68, 68, 0.1);
    color: #ef4444;
}

/* Unban (Green) */
.batch-btn.success {
    color: #64748b;
}

.batch-btn.success:hover {
    background: rgba(16, 185, 129, 0.1);
    color: #10b981;
}

/* Points (Yellow/Amber) */
.batch-btn[onclick*="Points"]:hover {
    background: rgba(245, 158, 11, 0.1);
    color: #f59e0b;
}

/* Tags (Purple) */
.batch-btn[onclick*="Tags"]:hover {
    background: rgba(139, 92, 246, 0.1);
    color: #8b5cf6;
}

/* Export (Indigo) */
.batch-btn[onclick*="Export"]:hover {
    background: rgba(99, 102, 241, 0.1);
    color: #6366f1;
}

/* Close Button (Circle) */
.batch-close-wrapper {
    margin-left: 12px;
    padding-left: 12px;
    border-left: 1px solid rgba(0, 0, 0, 0.08);
    flex-shrink: 0;
}

.batch-clear {
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 50%;
    background: rgba(241, 245, 249, 1);
    color: #94a3b8;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.batch-clear:hover {
    background: #e2e8f0;
    color: #475569;
    transform: rotate(90deg);
}

[data-theme="dark"] .batch-btn {
    color: #94a3b8;
}

[data-theme="dark"] .batch-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #f8fafc;
}

[data-theme="dark"] .batch-close-wrapper {
    border-left-color: rgba(255, 255, 255, 0.15);
}

[data-theme="dark"] .batch-clear {
    background: rgba(255, 255, 255, 0.1);
    color: #94a3b8;
}

[data-theme="dark"] .batch-clear:hover {
    background: rgba(255, 255, 255, 0.2);
    color: #fff;
}

/* ========================================
   BATCH SELECTION PILL (底部悬浮小条)
   ======================================== */
.batch-selection-pill {
    position: fixed;
    bottom: 24px;
    left: 50%;
    transform: translateX(-50%) translateY(100px);
    padding: 10px 16px;
    background: rgba(30, 41, 59, 0.95);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 50px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
    z-index: 9998;
    opacity: 0;
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.batch-selection-pill.active {
    transform: translateX(-50%) translateY(0);
    opacity: 1;
}

.batch-pill-content {
    display: flex;
    align-items: center;
    gap: 16px;
}

.batch-pill-count {
    display: flex;
    align-items: center;
    gap: 8px;
    color: #94a3b8;
    font-size: 0.9rem;
    white-space: nowrap;
}

.batch-pill-count i {
    color: #3b82f6;
}

.batch-pill-count strong {
    color: #fff;
    font-weight: 700;
}

.batch-pill-action {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 16px;
    border: none;
    border-radius: 20px;
    background: #3b82f6;
    color: #fff;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.batch-pill-action:hover {
    background: #2563eb;
    transform: scale(1.05);
}

.batch-pill-clear {
    width: 28px;
    height: 28px;
    border: none;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.1);
    color: #64748b;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.batch-pill-clear:hover {
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
}

/* ========================================
   BATCH ACTION MODAL (居中弹窗设计)
   ======================================== */
.batch-action-modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
}

.batch-action-modal-overlay.active {
    opacity: 1;
    pointer-events: auto;
}

.batch-action-modal {
    width: 400px;
    max-width: 90vw;
    background: #1a1a2e;
    border-radius: 20px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    box-shadow:
        0 25px 50px -12px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(255, 255, 255, 0.05);
    overflow: hidden;
    transform: scale(0.9) translateY(20px);
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.batch-action-modal-overlay.active .batch-action-modal {
    transform: scale(1) translateY(0);
}

.batch-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 20px 24px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.batch-modal-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: #fff;
}

.batch-modal-close {
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.1);
    color: #94a3b8;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.batch-modal-close:hover {
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
}

.batch-modal-info {
    padding: 16px 24px;
    color: #94a3b8;
    font-size: 0.95rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.batch-modal-info strong {
    color: #3b82f6;
    font-weight: 700;
}

.batch-modal-actions {
    padding: 16px;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
}

.batch-action-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    padding: 16px 12px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.03);
    color: #e2e8f0;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s ease;
}

.batch-action-item i {
    font-size: 1.3rem;
    color: #64748b;
    transition: color 0.2s ease;
}

.batch-action-item:hover {
    background: rgba(59, 130, 246, 0.1);
    border-color: rgba(59, 130, 246, 0.3);
}

.batch-action-item:hover i {
    color: #3b82f6;
}

.batch-action-item.danger:hover {
    background: rgba(239, 68, 68, 0.1);
    border-color: rgba(239, 68, 68, 0.3);
}

.batch-action-item.danger:hover i {
    color: #ef4444;
}

.batch-action-item.success:hover {
    background: rgba(16, 185, 129, 0.1);
    border-color: rgba(16, 185, 129, 0.3);
}

.batch-action-item.success:hover i {
    color: #10b981;
}

.batch-modal-footer {
    padding: 16px 24px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    display: flex;
    justify-content: center;
}

.batch-cancel-btn {
    padding: 10px 32px;
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 10px;
    background: transparent;
    color: #94a3b8;
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.2s ease;
}

.batch-cancel-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}

/* Tag option buttons in modal */
.tag-option {
    padding: 8px 16px;
    border: none;
    border-radius: 20px;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s ease;
}

.tag-option:hover {
    transform: scale(1.05);
}


/* Status Badges */
.status-badge {
    padding: 3px 8px;
    /* Further reduced */
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
