    justify-content: space-between;
    padding: 4px 0;
    /* Very tight rows */
    font-size: 0.9rem;
    border-bottom: 1px dashed rgba(255, 255, 255, 0.06);
}

.user-modal-left .info-row:last-child {
    border-bottom: none;
}

.user-modal-left .info-row span:first-child {
    color: #94a3b8;
}

.user-modal-left .info-row span:last-child {
    font-weight: 500;
    color: #f1f5f9;
}

/* Right Column */
.user-modal-right {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: rgba(255, 255, 255, 0.01);
}

/* Tab Navigation (Modern Capsules) */
.user-tab-nav {
    display: flex;
    justify-content: space-between;
    padding: 16px 24px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    position: relative;
    /* For indicator positioning */
}

/* Sliding Indicator */
.tab-indicator {
    position: absolute;
    bottom: -1px;
    left: 0;
    width: 0;
    height: 2px;
    background: #6b9ece;
    box-shadow: 0 -2px 8px rgba(107, 158, 206, 0.5);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    pointer-events: none;
    z-index: 10;
    opacity: 0;
}



.user-tab-btn {
    position: relative;
    padding: 12px 16px;
    background: transparent;
    border: none;
    color: #94a3b8;
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.2s;
    font-weight: 500;
}

.user-tab-btn:hover {
    color: #e2e8f0;
}

.user-tab-btn.active {
    color: #6b9ece;
}

/* Removed static ::after underline */


:root:not([data-theme="dark"]) .user-tab-btn.active {
    color: #6b9ece;
}

/* Tab Content */
.user-tab-content {
    flex: 1;
    padding: 8px 32px 24px 32px;
    /* Reduced top padding */
    overflow-y: auto;
}

/* Loading Spinner Center */
.modal-loading {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100%;
    width: 100%;
    min-height: 200px;
    /* Ensure visible height */
    color: var(--text-dim, #94a3b8);
    font-size: 0.9rem;
    gap: 8px;
    position: relative;
    overflow: hidden;
}

.users-tab-state {
    display: flex;
    flex-direction: column;
    gap: 18px;
    min-height: 100%;
}

.users-tab-state-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 18px;
    padding: 18px 20px;
    border-radius: 20px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background:
        radial-gradient(circle at top right, rgba(107, 158, 206, 0.14), transparent 36%),
        rgba(15, 23, 42, 0.46);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.users-tab-state--error .users-tab-state-header {
    background:
        radial-gradient(circle at top right, rgba(248, 113, 113, 0.14), transparent 38%),
        rgba(15, 23, 42, 0.52);
    border-color: rgba(248, 113, 113, 0.16);
}

.users-tab-state-copy {
    flex: 1;
    min-width: 0;
}

.users-tab-state-eyebrow {
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(148, 163, 184, 0.78);
}

.users-tab-state-title-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 10px;
}

.users-tab-state-icon {
    width: 38px;
    height: 38px;
    border-radius: 12px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    background: rgba(107, 158, 206, 0.12);
    border: 1px solid rgba(107, 158, 206, 0.18);
    color: #dbeafe;
}

.users-tab-state--error .users-tab-state-icon {
    background: rgba(248, 113, 113, 0.12);
    border-color: rgba(248, 113, 113, 0.22);
    color: #fecaca;
}

.users-tab-state-title {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #f8fafc;
    line-height: 1.35;
}

.users-tab-state-description {
    margin: 12px 0 0;
    color: rgba(203, 213, 225, 0.82);
    font-size: 0.84rem;
    line-height: 1.65;
}

.users-tab-state-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 30px;
    padding: 0 12px;
    border-radius: 999px;
    border: 1px solid rgba(107, 158, 206, 0.18);
    background: rgba(107, 158, 206, 0.12);
    color: #dbeafe;
    font-size: 0.74rem;
    font-weight: 600;
    white-space: nowrap;
}

.users-tab-state--error .users-tab-state-badge {
    border-color: rgba(248, 113, 113, 0.2);
    background: rgba(248, 113, 113, 0.12);
    color: #fecaca;
}

.users-tab-state-body {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.users-tab-state-actions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.users-tab-state-meta {
    color: rgba(148, 163, 184, 0.82);
    font-size: 0.8rem;
    line-height: 1.6;
}

.tab-toolbar.users-tab-toolbar-skeleton {
    padding: 0 !important;
    margin-bottom: 0 !important;
    height: auto !important;
}

.users-tab-skeleton-toolbar-actions {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    margin-left: auto;
}

.users-tab-skeleton {
    position: relative;
    overflow: hidden;
    display: inline-block;
    background: rgba(148, 163, 184, 0.14);
    border-radius: 999px;
}

.users-tab-skeleton::after {
    content: '';
    position: absolute;
    inset: 0;
    transform: translateX(-120%);
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.18), transparent);
    animation: userTabSkeletonSweep 1.35s ease-in-out infinite;
}

.users-tab-skeleton--toolbar-main {
    width: 126px;
    height: 26px;
}

.users-tab-skeleton--toolbar-action {
    width: 118px;
    height: 26px;
}

.users-tab-skeleton-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.users-tab-skeleton-card {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    padding: 18px 20px;
    border-radius: 18px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(255, 255, 255, 0.025);
}

.users-tab-skeleton-card-copy {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.users-tab-skeleton-card-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.users-tab-skeleton-card-side {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 10px;
    min-width: 108px;
}

.users-tab-skeleton--icon {
    width: 42px;
    height: 42px;
    border-radius: 14px;
    flex: 0 0 auto;
}

.users-tab-skeleton--avatar {
    border-radius: 999px;
}

.users-tab-skeleton--title {
    height: 16px;
    border-radius: 999px;
}

.users-tab-skeleton--line {
    height: 12px;
    border-radius: 999px;
}

.users-tab-skeleton--pill {
    height: 24px;
}

.users-tab-skeleton--amount {
    width: 84px;
    height: 18px;
}

.users-tab-skeleton--time {
    width: 68px;
    height: 12px;
}

.users-tab-skeleton--eyebrow {
    height: 11px;
}

.users-tab-skeleton--headline {
    height: 20px;
    margin-top: 12px;
}

.users-tab-skeleton--stat-value {
