}

.users-tab-skeleton--w-line-wide {
    width: min(78%, 420px);
}

.users-tab-skeleton--w-line-mid {
    width: min(64%, 320px);
}

.users-tab-skeleton--w-line-short {
    width: min(42%, 220px);
}

.users-tab-skeleton--w-chip-wide {
    width: 112px;
}

.users-tab-skeleton--w-chip-mid {
    width: 88px;
}

.users-tab-skeleton--w-chip-short {
    width: 62px;
}

.users-tab-skeleton-dashboard {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.users-tab-skeleton-hero-card,
.users-tab-skeleton-panel,
.users-tab-skeleton-stat-card,
.users-tab-skeleton-composer {
    border-radius: 20px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(255, 255, 255, 0.03);
}

.users-tab-skeleton-hero-card {
    padding: 20px;
}

.users-tab-skeleton-stats {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
}

.users-tab-skeleton-stat-card {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 16px;
}

.users-tab-skeleton-panels {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
