}

.users-tab-skeleton-panel {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 18px;
}

.users-tab-skeleton-composer {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 16px 18px;
}

.users-tab-retry-btn {
    min-height: 34px;
    padding: 0 16px;
}

.users-tab-inline-banner {
    display: flex;
    align-items: center;
    gap: 10px;
    min-height: 40px;
    margin-bottom: 14px;
    padding: 0 14px;
    border-radius: 14px;
    border: 1px solid rgba(107, 158, 206, 0.16);
    background: rgba(107, 158, 206, 0.1);
    color: #dbeafe;
    font-size: 0.8rem;
    line-height: 1.5;
