}

.users-tab-inline-banner.is-closing {
    opacity: 0;
    transform: translateY(-4px);
}

.users-tab-refresh-shell {
    position: relative;
    min-height: 120px;
}

.users-tab-refresh-shell.is-refreshing {
    pointer-events: none;
}

.users-tab-refresh-shell--notes {
    flex: 1;
    min-height: 220px;
}

.users-tab-refresh-overlay {
    position: absolute;
    inset: 0;
    z-index: 2;
    padding: 12px;
    border-radius: 18px;
    background: rgba(15, 23, 42, 0.62);
    backdrop-filter: blur(6px);
}

.users-tab-refresh-overlay-panel {
    height: 100%;
    min-height: 100%;
    border-radius: 16px;
    border: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(15, 23, 42, 0.28);
    padding: 12px;
    overflow: hidden;
}

.users-tab-standalone-actions,
.users-tab-toolbar-actions {
    display: inline-flex;
