    gap: 10px;
    flex-wrap: wrap;
}

.users-tab-standalone-actions {
    justify-content: flex-end;
}

.users-tab-refresh-btn {
    min-width: 84px;
}

@keyframes userTabSkeletonSweep {
    100% {
        transform: translateX(120%);
    }
}

