/* ========================================
   MODAL CUSTOM COMPONENTS (REFINED)
   ======================================== */

/* Custom Dropdown */
.modal-dropdown {
    position: relative;
    margin-top: 8px;
}

.modal-dropdown-trigger {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
    padding: 8px 16px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    cursor: pointer;
    font-size: 0.85rem;
    color: #94a3b8;
    transition: all 0.2s;
}

.modal-dropdown-trigger:hover {
    background: rgba(255, 255, 255, 0.08);
    color: white;
    border-color: rgba(255, 255, 255, 0.2);
}

.modal-dropdown-trigger i {
    font-size: 0.7rem;
    transition: transform 0.2s;
    opacity: 0.7;
}

.modal-dropdown.open .modal-dropdown-trigger i {
    transform: rotate(180deg);
}

.modal-dropdown-menu {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    margin-top: 6px;
    background: #1e293b;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 10px;
    box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.5);
    z-index: 100;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-8px);
    transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
    overflow: hidden;
}

.modal-dropdown.open .modal-dropdown-menu {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

.modal-dropdown-item {
    padding: 10px 16px;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.15s;
    color: #cbd5e1;
    border-bottom: 1px solid rgba(255, 255, 255, 0.02);
}

.modal-dropdown-item:last-child {
    border-bottom: none;
}

.modal-dropdown-item:hover {
    background: rgba(107, 158, 206, 0.1);
    color: #6b9ece;
    padding-left: 16px;
    /* Restore padding (was 20px in old style) */
    transform: translateY(-0.5px);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    /* Dark mode shadow */
    z-index: 1;
    position: relative;
    border-radius: 6px;
}

/* Modal Tags */
.modal-tags-container {
    display: flex;
    flex-wrap: wrap;
    /* Allow wrapping */
    gap: 8px;
