/* =========================================
   User List Upgrades (v3.0 - Visual Life) 
   ========================================= */

/* 1. Status Dots (Last Active) */
.active-status {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.85rem;
    color: var(--text-dim);
    font-weight: 500;
}

.status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: #cbd5e1;
    /* Default Offline */
    transition: all 0.3s ease;
}

.status-dot.online {
    background-color: #10b981;
    box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.2);
    animation: breathe 2s infinite ease-in-out;
}

.status-dot.away {
    background-color: #f59e0b;
}

@keyframes breathe {
    0% {
        transform: scale(0.95);
        opacity: 0.8;
    }

    50% {
        transform: scale(1.1);
        opacity: 1;
        box-shadow: 0 0 8px rgba(16, 185, 129, 0.4);
    }

    100% {
        transform: scale(0.95);
        opacity: 0.8;
    }
}

/* 2. Quick Actions (Hover Reveal) */
.user-row {
    position: relative;
    transition: background-color 0.2s;
}

/* Prevent cell overflow clipping */
.user-row td {
    overflow: visible !important;
}

/* Container for quick actions (revealed on hover) */
.action-cell {
    position: relative;
    text-align: right;
    /* Ensure enough width for the buttons so they don't overflow */
    min-width: 110px;
}

.quick-actions {
    position: absolute;
    right: 0;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    gap: 6px;
    justify-content: flex-end;
    opacity: 0;
    pointer-events: none;
    transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
    /* Background to cover the static ellipsis */
    background: transparent;
}

.user-row:hover .quick-actions {
    opacity: 1;
    pointer-events: auto;
}

.user-row:hover .action-static {
    opacity: 0;
    /* Fade out to prevent reflow */
}

.quick-btn {
    width: 28px;
    height: 28px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(0, 0, 0, 0.1);
    background: white;
    color: #64748b;
    cursor: pointer;
    transition: all 0.2s;
    font-size: 0.8rem;
}

.quick-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
}

.quick-btn.notify:hover {
    color: #3b82f6;
    border-color: #3b82f6;
    background: rgba(59, 130, 246, 0.05);
}

.quick-btn.ban:hover {
    color: #ef4444;
    border-color: #ef4444;
    background: rgba(239, 68, 68, 0.05);
}

.quick-btn.detail:hover {
    color: #6366f1;
    border-color: #6366f1;
    background: rgba(99, 102, 241, 0.05);
}

/* Dark Mode Support */
[data-theme="dark"] .quick-btn {
    background: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.1);
    color: #94a3b8;
}

/* ========================================
   BATCH ACTION MODALS
   ======================================== */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: 10000;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}

.modal-overlay.active {
    opacity: 1;
    visibility: visible;
}

.modal-content {
    background: var(--bg-color, #fff);
    border-radius: 16px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    border: 1px solid var(--border-color, rgba(0, 0, 0, 0.1));
    max-width: 90vw;
    max-height: 90vh;
    overflow: hidden;
    transform: scale(0.95);
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.modal-overlay.active .modal-content {
    transform: scale(1);
}

[data-theme="dark"] .modal-content {
    background: #1e1e1e;
    border-color: rgba(255, 255, 255, 0.1);
}

.modal-header {
