    justify-content: space-between;
    gap: 12px;
    padding: 10px 12px;
    border-radius: 12px;
    background: rgba(15, 23, 42, 0.26);
    border: 1px solid rgba(148, 163, 184, 0.08);
}

.points-generate-preview__meta-item span {
    font-size: 0.8rem;
    color: rgba(148, 163, 184, 0.82);
}

.points-generate-preview__meta-item strong {
    font-size: 0.85rem;
