/* Lookup Panel */
.lookup-panel {
    max-width: 500px;
}

.lookup-panel h3 {
    font-size: 1.2rem;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 10px;
}

.lookup-panel h3 i {
    color: var(--accent-purple);
}

.lookup-input-row {
    display: flex;
    gap: 12px;
}

.lookup-input-row input {
    flex: 1;
    padding: 12px 16px;
    background: rgba(0, 0, 0, 0.2);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    color: var(--text-main);
    font-family: 'Monaco', 'Consolas', monospace;
    font-size: 0.95rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.lookup-input-row input:focus {
    outline: none;
    border-color: var(--accent-purple);
}

.lookup-result {
    margin-top: 20px;
    width: 100%;
    min-width: 0;
}

.lookup-card {
    background: rgba(0, 0, 0, 0.15);
    width: 100%;
    box-sizing: border-box;
    border-radius: 12px;
    padding: 20px;
    border: 1px solid var(--card-border);
    animation: lookupSlideUp 0.35s ease-out 0.15s both;
}

@keyframes lookupSlideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.lookup-card.valid {
    border-color: rgba(34, 197, 94, 0.3);
}

.lookup-card.invalid {
    border-color: rgba(239, 68, 68, 0.3);
}

.lookup-status {
    font-size: 1.1rem;
    font-weight: 500;
    margin-bottom: 16px;
}

.lookup-detail {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    /* top align for multi-line */
    padding: 10px 0;
    /* Slightly more breathing room */
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.lookup-detail:last-child {
    border-bottom: none;
}

.lookup-detail .label {
    color: var(--text-dim);
    flex-shrink: 0;
    /* Don't shrink label */
    margin-right: 16px;
}

.lookup-detail .value {
    font-weight: 500;
    text-align: right;
    /* Right align values */
    flex: 1;
    word-break: break-word;
    /* Handle long text */
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    /* Align flex children to right */
}

.lookup-detail .value.code-value {
    font-family: 'SF Mono', 'Roboto Mono', 'Monaco', monospace;
    color: var(--accent-starry, #6b9ece);
