    border: 1px solid rgba(148, 163, 184, 0.16);
    background: rgba(18, 26, 46, 0.72);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.lookup-summary-card__label {
    font-size: 0.78rem;
    color: rgba(148, 163, 184, 0.88);
    letter-spacing: 0.03em;
    text-transform: uppercase;
}

.lookup-summary-card__value {
    font-size: 1rem;
    line-height: 1.4;
    color: var(--text-main);
}

.lookup-summary-card--success {
    border-color: rgba(52, 211, 153, 0.18);
}

.lookup-summary-card--danger {
    border-color: rgba(248, 113, 113, 0.18);
}

.lookup-summary-card--info {
    border-color: rgba(107, 158, 206, 0.2);
}

.lookup-content-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.28fr) minmax(300px, 0.72fr);
    gap: 18px;
    align-items: start;
}

.lookup-section {
    position: relative;
    padding: 18px;
    border-radius: 18px;
    border: 1px solid rgba(148, 163, 184, 0.14);
    background: rgba(15, 22, 39, 0.78);
    align-self: start;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.lookup-section__title {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 12px;
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: rgba(148, 163, 184, 0.9);
}

.lookup-section__title::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 999px;
    background: rgba(107, 158, 206, 0.82);
    box-shadow: 0 0 0 4px rgba(107, 158, 206, 0.08);
}

.lookup-section__body {
    color: var(--text-dim);
    line-height: 1.7;
}

.lookup-field-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 12px;
}

.lookup-field-card {
    display: flex;
    flex-direction: column;
    position: relative;
    gap: 10px;
    min-height: 0;
    padding: 14px 16px;
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.14);
    background: rgba(16, 23, 41, 0.7);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

.lookup-field-card--wide {
    grid-column: 1 / -1;
}

.lookup-field-card__label {
    font-size: 0.76rem;
    font-weight: 700;
    color: rgba(148, 163, 184, 0.86);
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.lookup-field-card__value {
    display: flex;
    flex-direction: column;
    gap: 8px;
    color: var(--text-main);
    font-size: 0.96rem;
    font-weight: 600;
    line-height: 1.7;
    overflow-wrap: anywhere;
    word-break: normal;
}

.lookup-field-card--success {
    border-color: rgba(52, 211, 153, 0.18);
}

.lookup-field-card--danger {
    border-color: rgba(248, 113, 113, 0.18);
}

.lookup-field-card--info {
    border-color: rgba(107, 158, 206, 0.18);
}

.lookup-field-card--mono .lookup-field-card__value {
    font-family: 'SF Mono', 'Monaco', 'Consolas', monospace;
    font-size: 0.96rem;
    line-height: 1.7;
    letter-spacing: 0.03em;
}

.lookup-timeline {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.lookup-timeline-item {
    display: grid;
    grid-template-columns: 34px 1fr;
    position: relative;
    gap: 14px;
    padding: 14px 16px;
    border-radius: 16px;
    border: 1px solid rgba(148, 163, 184, 0.12);
    background: rgba(16, 23, 41, 0.72);
}

.lookup-timeline-item__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border-radius: 10px;
    background: rgba(107, 158, 206, 0.14);
    color: #dbeafe;
}

.lookup-timeline-item--used .lookup-timeline-item__icon {
    background: rgba(34, 197, 94, 0.14);
    color: #bbf7d0;
}

.lookup-timeline-item--revoked .lookup-timeline-item__icon {
    background: rgba(239, 68, 68, 0.14);
    color: #fecaca;
}

.lookup-timeline-item--pending .lookup-timeline-item__icon,
.lookup-timeline-item--expired .lookup-timeline-item__icon {
    background: rgba(245, 158, 11, 0.14);
    color: #fde68a;
}

.lookup-timeline-item__content {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;
}

.lookup-timeline-item__title {
    color: var(--text-main);
    font-weight: 600;
}

.lookup-timeline-item__meta {
    color: rgba(148, 163, 184, 0.9);
    font-size: 0.82rem;
}

.lookup-timeline-item__detail {
    color: var(--text-dim);
    line-height: 1.55;
}

/* Specific color helpers */
.text-success {
    color: #10b981;
}

.text-danger {
    color: #ef4444;
}

.text-warning {
    color: #f59e0b;
}

.text-highlight {
    color: #6b9ece;
}

/* Light Mode - Lookup Card */
:root:not([data-theme="dark"]) .lookup-card {
    background: #ffffff;
    border-color: rgba(0, 0, 0, 0.1);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
}

:root:not([data-theme="dark"]) .lookup-card.valid {
    border-color: rgba(34, 197, 94, 0.4);
    background: rgba(34, 197, 94, 0.03);
}

:root:not([data-theme="dark"]) .lookup-card.invalid {
    border-color: rgba(239, 68, 68, 0.4);
    background: rgba(239, 68, 68, 0.03);
}

:root:not([data-theme="dark"]) .lookup-detail {
    border-bottom-color: rgba(0, 0, 0, 0.06);
}

/* Empty/Loading States */
.empty-cell,
.loading-cell,
.error-cell {
    text-align: center;
    padding: 40px !important;
    color: var(--text-dim);
}

.error-cell {
    color: #ef4444;
}

/* Refined Points Module Styles */

#points-view-generate {
    padding-bottom: 90px;
}

#points-view-batches {
    padding-bottom: 90px;
}

.points-batches-shell {
    max-width: 1300px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
