/* Batch Management Toolbar - lifted above the table panel */
#points-view-batches .admin-toolbar.batch-toolbar-inside {
    margin: 0;
    padding: 0;
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

#points-view-batches .glass-panel {
    width: 100%;
    max-width: none;
    margin: 0;
    padding: 28px;
    border-radius: 16px;
    overflow: visible;
}

#points-view-batches .glass-panel.users-table-panel {
    min-height: 612px;
    display: flex;
    flex-direction: column;
}

#points-view-batches .toolbar-left {
    display: flex;
    align-items: center;
    gap: 10px;
    /* Match :is(#module-users, #module-discounts, #module-tickets) .toolbar-left gap */
    flex-wrap: wrap;
}

#points-view-batches .filter-dropdowns {
    display: flex;
    gap: 10px;
    /* Match :is(#module-users, #module-discounts, #module-tickets) .filter-group gap */
}

/* Search Bar - Mirrored from :is(#module-users, #module-discounts, #module-tickets) .search-bar */
#points-view-batches .search-bar {
    position: relative;
    width: 280px;
    max-width: 100%;
    flex-shrink: 0;
    margin: 0;
    /* Reset any previous margins */
    padding: 0;
    border: none;
    background: transparent;
}

#points-view-batches .search-bar input {
    width: 100%;
    height: 34px;
    /* Match user module height */
    padding: 0 12px 0 36px;
    /* Match user module padding */
    background-color: rgba(255, 255, 255, 0.8);
    border: 1px solid rgba(0, 0, 0, 0.08);
    border-radius: 8px;
    color: #1e293b;
    font-size: 0.85rem;
    box-sizing: border-box;
    transition: all 0.2s;
    margin: 0;
    /* Reset */
}

#points-view-batches .search-bar input::placeholder {
    color: #64748b;
}

/* Specific focus state to match User Module */
#points-view-batches .search-bar input:focus {
    background-color: #ffffff !important;
    border-color: #6b9ece !important;
    outline: none !important;
    box-shadow: none !important;
}

#points-view-batches .search-bar i {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: #64748b;
    font-size: 0.8rem;
    pointer-events: none;
}

/* Filter Buttons - Match :is(#module-users, #module-discounts, #module-tickets) .filter-select style */
#points-view-batches .filter-btn {
    height: 34px;
    /* Match search input height */
    padding: 0 16px;
    background-color: rgba(255, 255, 255, 0.8);
    border: 1px solid rgba(0, 0, 0, 0.08);
    border-radius: 8px;
    /* Match search bar radius */
    color: #1e293b;
    font-size: 0.85rem;
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    transition: all 0.2s;
    /* Safari mobile touch event fixes */
    -webkit-tap-highlight-color: rgba(107, 158, 206, 0.3);
    touch-action: manipulation;
    position: relative;
    z-index: 10;
}

#points-view-batches .filter-btn:hover {
    background-color: #ffffff;
    border-color: rgba(0, 0, 0, 0.15);
}

#points-view-batches .filter-dropdown.open .filter-btn {
    border-color: #6b9ece;
    background-color: #ffffff;
}

/* Dark Mode Overrides for Batch Toolbar */
[data-theme="dark"] #points-view-batches .search-bar input {
    background-color: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.1);
    color: #f1f5f9;
}

[data-theme="dark"] #points-view-batches .search-bar input::placeholder {
    color: rgba(255, 255, 255, 0.4);
}

[data-theme="dark"] #points-view-batches .search-bar input:focus {
    background-color: rgba(255, 255, 255, 0.08) !important;
    border-color: #6b9ece !important;
}

[data-theme="dark"] #points-view-batches .search-bar i {
    color: rgba(255, 255, 255, 0.5);
}

[data-theme="dark"] #points-view-batches .filter-btn {
    background-color: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.1);
    color: #f1f5f9;
}

[data-theme="dark"] #points-view-batches .filter-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.2);
}

[data-theme="dark"] #points-view-batches .filter-dropdown.open .filter-btn {
    border-color: #6b9ece;
}

/* Export Dropdown Popup Styles */
#points-view-batches #batchExportPopup,
#points-view-batches .filter-dropdown[data-filter="batchExport"] .filter-popup {
    position: absolute;
    top: 100%;
    right: 0;
    margin-top: 8px;
    min-width: 160px;
    background: #ffffff;
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: 10px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15);
    z-index: 1000;
    padding: 6px;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-8px);
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Show popup when .show class is added by JS, or when parent has .open */
#points-view-batches #batchExportPopup.show,
#points-view-batches .filter-dropdown.open .filter-popup {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

[data-theme="dark"] #points-view-batches #batchExportPopup,
[data-theme="dark"] #points-view-batches .filter-dropdown[data-filter="batchExport"] .filter-popup {
    background: #1e293b;
    border-color: rgba(255, 255, 255, 0.1);
}

#points-view-batches .filter-popup .filter-option {
    display: flex;
    align-items: center;
