[data-theme="dark"] #points-view-batches .filter-popup .filter-option {
    color: #f1f5f9;
}

[data-theme="dark"] #points-view-batches .filter-popup .filter-option:hover {
    background: rgba(255, 255, 255, 0.1);
}

