        flex: 1 1 calc(50% - 8px);
        text-align: center;
        justify-content: center;
    }

    .points-batch-risk-row {
        gap: 5px;
    }

    /* Reduce panel padding on mobile */
    #points-view-batches .glass-panel {
        padding: 16px 12px;
    }

    /* CRITICAL FIX: Allow toolbar to show filter dropdowns above overflow:auto container */
    #points-view-batches .admin-toolbar.batch-toolbar-inside {
        position: relative;
        z-index: 100;
        overflow: visible;
    }

    /* Ensure glass-panel allows overflow for toolbar */
    #points-view-batches .glass-panel:not(.users-table-panel) {
        overflow: visible;
    }

    /* Ensure filter-dropdowns container allows overflow */
    #points-view-batches .filter-dropdowns {
        overflow: visible;
        position: relative;
        z-index: 101;
    }

    /* CRITICAL FIX: Filter dropdowns - use relative positioning for parent */
    #points-view-batches .filter-dropdown {
        position: relative;
    }

    /* Filter popups - use absolute positioning to scroll with page */
    #points-view-batches .filter-dropdown .filter-popup,
    #points-view-batches .filter-dropdown .glass-popup,
    #points-view-batches #batchExportPopup {
        position: absolute;
        top: var(--popup-top, calc(100% + 4px));
        left: var(--popup-left, 0px);
        right: auto;
        width: auto;
        min-width: 100px;
        max-width: calc(100vw - 24px);
        max-height: 60vh;
        overflow-y: auto;
        overflow-x: hidden;
        z-index: 9999;
        transform: none !important;
        margin-top: 0;
        transition: none !important;
        box-sizing: border-box;
    }

    /* Custom date range on mobile - more compact */
    #points-view-batches .filter-custom-date {
        padding: 6px;
        text-align: center;
    }

    #points-view-batches .filter-custom-date label {
        font-size: 0.7rem;
        margin-bottom: 4px;
        text-align: center;
    }

    #points-view-batches .filter-custom-date input {
        width: 100%;
        max-width: 100px;
        padding: 4px 6px;
        font-size: 0.75rem;
        text-align: center;
    }

    #points-view-batches .filter-custom-date span {
        font-size: 0.7rem;
        margin: 2px 0;
    }

    /* Remove button highlight/focus effect on mobile */
    #points-view-batches .filter-btn:focus,
    #points-view-batches .filter-btn:active,
    #points-view-batches .filter-dropdown.open .filter-btn {
        outline: none;
        box-shadow: none;
        background-color: rgba(255, 255, 255, 0.05);
        border-color: rgba(255, 255, 255, 0.15);
    }

    /* Also fix batch menu popup */
    #points-view-batches .batch-menu-popup {
        position: fixed;
        left: 12px;
        right: 12px;
        top: auto;
        bottom: auto;
        z-index: 9999;
    }

    #points-view-batches .batch-menu-popup.show {
        top: var(--popup-top, 200px);
    }

    /* Toolbar: Stack vertically */
    #points-view-batches .admin-toolbar.batch-toolbar-inside {
        flex-direction: column;
        align-items: stretch;
        gap: 12px;
    }

    /* Toolbar left: Stack search and filters */
    #points-view-batches .toolbar-left {
        flex-direction: column;
        align-items: stretch;
        gap: 12px;
        width: 100%;
    }

    /* Search bar: Full width */
    #points-view-batches .search-bar {
