/* --- Segmented Pills with Sliding Indicator --- */
.scope-options-pills {
    display: flex;
    gap: 0;
    padding: 4px;
    background: rgba(0, 0, 0, 0.2);
    border-radius: 10px;
    position: relative;
    /* CSS variables for sliding indicator - set by JS */
    --pill-count: 4;
    --active-index: 0;
    --indicator-color: rgba(59, 130, 246, 0.25);
    --indicator-border: rgba(59, 130, 246, 0.5);
}

.scope-options-pills--count-4 {
