    --pill-count: 5;
}

.scope-options-pills--index-0 {
    --active-index: 0;
}

.scope-options-pills--index-1 {
    --active-index: 1;
}

.scope-options-pills--index-2 {
    --active-index: 2;
}

.scope-options-pills--index-3 {
    --active-index: 3;
}

.scope-options-pills--index-4 {
    --active-index: 4;
}

.scope-options-pills--tone-unban {
    --indicator-color: rgba(59, 130, 246, 0.25);
    --indicator-border: rgba(59, 130, 246, 0.5);
}

.scope-options-pills--tone-temp {
    --indicator-color: rgba(245, 158, 11, 0.2);
    --indicator-border: rgba(245, 158, 11, 0.5);
}

.scope-options-pills--tone-permanent {
    --indicator-color: rgba(239, 68, 68, 0.25);
    --indicator-border: rgba(239, 68, 68, 0.5);
}

/* Sliding indicator background */
.scope-options-pills.no-indicator::before {
    display: none;
}

.scope-options-pills::before {
    content: '';
    position: absolute;
    top: 4px;
    bottom: 4px;
    left: 4px;
    width: calc((100% - 8px) / var(--pill-count));
    background: var(--indicator-color);
    border: 1px solid var(--indicator-border);
    border-radius: 8px;
    transform: translateX(calc(var(--active-index) * 100%));
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
        background 0.3s ease,
        border-color 0.3s ease;
    z-index: 0;
    pointer-events: none;
}

.scope-pill {
    flex: 1;
    text-align: center;
    padding: 8px 0;
    border-radius: 8px;
    font-size: 0.85rem;
    font-weight: 500;
    cursor: pointer;
    color: #64748b;
    transition: color 0.3s ease, font-weight 0.2s ease;
    border: 1px solid transparent;
    position: relative;
    z-index: 1;
    background: transparent !important;
    /* Let the sliding indicator be the background */
}

.scope-pill:hover {
    color: #cbd5e1;
}

/* Selected pill - only change text color, background is handled by indicator */
.scope-pill.selected {
    color: #60a5fa;
    font-weight: 600;
}

/* Selected: Normal (Blue) */
.scope-pill[data-days="unban"].selected {
