/* ========================================
   USERS BATCH EXPORT MODAL
   ======================================== */

.batch-export-modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: 10000;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.3s ease, visibility 0.3s ease;
}

.batch-export-modal-overlay.active {
    opacity: 1;
    visibility: visible;
}

.batch-export-modal {
    width: 380px;
    max-width: 90vw;
    background: var(--bg-color, #fff);
    color: var(--text-main, #1e1e1e);
    border-radius: 12px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.2);
    border: 1px solid var(--border-color, rgba(0, 0, 0, 0.1));
    overflow: hidden;
    transform: scale(0.95);
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.batch-export-modal-overlay.active .batch-export-modal {
    transform: scale(1);
}

.batch-export-modal-header {
    padding: 14px 16px;
    border-bottom: 1px solid var(--border-color, rgba(0, 0, 0, 0.1));
    text-align: center;
}

.batch-export-modal-title {
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-main);
}

.batch-export-modal-body {
    padding: 14px 20px;
}

.batch-export-modal-summary {
    margin-bottom: 14px;
    font-size: 0.95rem;
    color: var(--text-main);
}

.batch-export-modal-count {
    font-weight: 700;
    color: #3b82f6;
}

.batch-export-modal-section {
    margin-bottom: 16px;
}

.batch-export-modal-section-compact {
    margin-bottom: 6px;
}

.batch-export-modal-section-title {
    color: var(--text-dim, #666);
    margin-bottom: 8px;
    font-size: 0.85rem;
}

.batch-export-modal-options {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.batch-export-modal-options-tight {
    gap: 6px;
}

.batch-export-modal-option {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    color: var(--text-main);
    font-size: 0.9rem;
}

.batch-export-modal-option input {
    accent-color: #3b82f6;
}

.batch-export-modal-option.is-disabled {
    opacity: 0.7;
    cursor: default;
}

.batch-export-modal-footer {
    padding: 14px 20px;
    border-top: 1px solid var(--border-color, rgba(0, 0, 0, 0.1));
    display: flex;
    justify-content: center;
    gap: 16px;
}

.batch-export-modal-btn {
    padding: 6px 24px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
}

.batch-export-modal-btn.modal-btn-cancel {
    border: 1px solid var(--border-color, rgba(0, 0, 0, 0.2));
    background: transparent;
    color: var(--text-main);
}

.batch-export-modal-btn-primary {
    border: none;
    background: #3b82f6;
    color: #fff;
    font-weight: 600;
}

