.payments-kpi-card-visual .kpi-icon {
    background: linear-gradient(135deg, #6b9ece 0%, #5a8cba 100%);
    box-shadow: 0 10px 30px rgba(107, 158, 206, 0.25);
    width: 54px;
    height: 54px;
    border-radius: 16px;
    font-size: 1.28rem;
}

.payments-kpi-card-visual.is-warning .kpi-icon {
    background: linear-gradient(135deg, #f59e0b, #d97706);
    box-shadow: 0 10px 30px rgba(245, 158, 11, 0.2);
}

.payments-kpi-card-visual.is-critical .kpi-icon {
    background: linear-gradient(135deg, #ef4444, #dc2626);
    box-shadow: 0 10px 30px rgba(239, 68, 68, 0.2);
}

.payments-kpi-card-visual.is-info .kpi-icon {
    background: linear-gradient(135deg, #60a5fa, #2563eb);
    box-shadow: 0 10px 30px rgba(96, 165, 250, 0.2);
}

.payments-kpi-card-visual.is-money .kpi-icon {
    background: linear-gradient(135deg, #7bb0df, #588bc2);
    box-shadow: 0 10px 30px rgba(123, 176, 223, 0.22);
}

.payments-kpi-footnote {
    margin-top: 8px;
    font-size: 0.82rem;
    color: var(--text-dim);
    line-height: 1.6;
}

.payments-kpi-value {
    font-size: clamp(1.75rem, 1.85vw, 2.2rem);
    line-height: 1;
    font-weight: 700;
    color: var(--text-main);
    white-space: nowrap;
    overflow-wrap: normal;
}

.payments-kpi-label-row {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

.payments-kpi-label {
    font-size: 0.9rem;
    color: #f3f6fc;
    line-height: 1.2;
}

.payments-info-chip {
    position: relative;
    width: 18px;
    height: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    appearance: none;
    background: transparent;
    border: 0;
    color: #93c5fd;
    flex-shrink: 0;
    cursor: help;
    opacity: 0.92;
}

.payments-info-tooltip {
    position: absolute;
    left: 50%;
    bottom: calc(100% + 12px);
    transform: translate(-50%, 8px);
    max-width: min(320px, calc(100vw - 24px));
    width: max-content;
    padding: 12px 14px;
    border-radius: 16px;
    border: 1px solid rgba(191, 219, 254, 0.22);
    background: rgba(26, 37, 53, 0.42);
    backdrop-filter: blur(34px) saturate(200%);
    -webkit-backdrop-filter: blur(34px) saturate(200%);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.18),
        inset 0 -1px 0 rgba(255, 255, 255, 0.04),
        0 24px 64px rgba(15, 23, 42, 0.38);
    color: #e5f0ff;
    font-size: 0.79rem;
    line-height: 1.65;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.16s ease, transform 0.16s ease;
    z-index: 50;
    white-space: normal;
    visibility: hidden;
}

.payments-info-tooltip::before {
    content: '';
    position: absolute;
    left: 50%;
    bottom: -7px;
    width: 14px;
    height: 14px;
    border-right: 1px solid rgba(191, 219, 254, 0.22);
    border-bottom: 1px solid rgba(191, 219, 254, 0.22);
    background: rgba(26, 37, 53, 0.42);
    backdrop-filter: blur(26px) saturate(190%);
    -webkit-backdrop-filter: blur(26px) saturate(190%);
    transform: translateX(-50%) rotate(45deg);
}

.payments-info-chip:hover .payments-info-tooltip,
.payments-info-chip:focus-visible .payments-info-tooltip,
.payments-info-chip:focus-within .payments-info-tooltip {
    opacity: 1;
    transform: translate(-50%, 0);
    visibility: visible;
}

.payments-info-glyph {
    width: 13px;
    height: 13px;
    display: block;
    background:
        radial-gradient(circle at 50% 50%, rgba(219, 234, 254, 0.98) 0 22%, transparent 24%),
        linear-gradient(180deg, transparent 0 18%, currentColor 20% 80%, transparent 82%),
        linear-gradient(90deg, transparent 0 18%, currentColor 20% 80%, transparent 82%);
    transform: rotate(45deg);
    border-radius: 2px;
    filter: drop-shadow(0 0 10px rgba(96, 165, 250, 0.34));
}

.payments-kpi-card,
.payments-panel {
