/* ---- Empty & Error States ---- */
.empty-state,
.error-state {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 200px;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.error-state {
    color: #ef4444;
}

/* ---- Chart Wide (spans 2 columns) ---- */
.chart-wide {
    grid-column: span 2;
}

@media (max-width: 1200px) {
    .chart-wide {
        grid-column: span 1;
    }
}

/* ---- Activity Heatmap ---- */
.heatmap-container {
    padding: 16px 20px;
    overflow-x: auto;
}

.heatmap-grid {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 500px;
}

.heatmap-row {
    display: flex;
    align-items: center;
    gap: 2px;
}

.heatmap-row.header {
    margin-bottom: 4px;
}

.heatmap-label {
    width: 40px;
    font-size: 0.75rem;
    color: var(--text-secondary);
    text-align: right;
    padding-right: 8px;
    flex-shrink: 0;
}

.heatmap-hour {
    flex: 2;
    text-align: center;
    font-size: 0.7rem;
    color: var(--text-secondary);
}

.heatmap-cell {
    flex: 1;
    height: 20px;
    border-radius: 3px;
    min-width: 16px;
    transition: transform 0.15s, box-shadow 0.15s;
    cursor: pointer;
}

.heatmap-cell--level-0 {
    background: #ebedf0;
}

.heatmap-cell--level-1 {
    background: #9be9a8;
}

.heatmap-cell--level-2 {
    background: #40c463;
}

.heatmap-cell--level-3 {
    background: #30a14e;
}

.heatmap-cell--level-4 {
    background: #216e39;
}

[data-theme="dark"] .heatmap-cell--level-0 {
    background: #161b22;
}

[data-theme="dark"] .heatmap-cell--level-1 {
    background: #0e4429;
}

[data-theme="dark"] .heatmap-cell--level-2 {
    background: #006d32;
}

[data-theme="dark"] .heatmap-cell--level-3 {
    background: #26a641;
}

[data-theme="dark"] .heatmap-cell--level-4 {
    background: #39d353;
}

.heatmap-cell:hover {
    transform: scale(1.2);
    box-shadow: 0 2px 8px rgba(107, 158, 206, 0.4);
    z-index: 1;
}

/* ---- Contributors List ---- */
.contributors-list {
    padding: 16px 20px;
    max-height: 320px;
    overflow-y: auto;
}

.contributor-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 0;
    border-bottom: 1px solid var(--card-border);
}

.contributor-item:last-child {
    border-bottom: none;
}

.contributor-avatar {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid var(--card-border);
}

.contributor-info {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.contributor-name {
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--text-main);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.contributor-name-btn {
    display: inline-block;
    max-width: 100%;
    padding: 0;
    border: none;
    background: none;
    font: inherit;
    text-align: left;
    cursor: pointer;
    transition: color 0.2s ease;
}

.contributor-name-btn:hover,
.contributor-name-btn:focus-visible {
    color: var(--accent-starry);
}

.contributor-name-btn:focus-visible {
    outline: 2px solid rgba(107, 158, 206, 0.28);
    outline-offset: 2px;
    border-radius: 6px;
}

.contributor-stats {
    display: flex;
    gap: 12px;
    font-size: 0.75rem;
    color: var(--text-secondary);
}

.contributor-stats i {
    margin-right: 3px;
}

.contributor-score {
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--accent-starry, #6b9ece);
    min-width: 40px;
    text-align: right;
}

/* Loading text inside cards */
.chart-body .loading-text {
    position: relative;
    display: block;
    min-height: 200px;
    border-radius: 18px;
    overflow: hidden;
    color: transparent;
    font-size: 0;
    background: rgba(15, 23, 42, 0.24);
    border: 1px solid rgba(255, 255, 255, 0.06);
}

.chart-body .loading-text::before {
    content: "";
    position: absolute;
    inset: 22px 20px;
    border-radius: 14px;
    background:
        linear-gradient(rgba(148, 163, 184, 0.18), rgba(148, 163, 184, 0.18)) 0 0 / 48% 14px no-repeat,
        linear-gradient(rgba(148, 163, 184, 0.12), rgba(148, 163, 184, 0.12)) 0 36px / 100% 10px no-repeat,
        linear-gradient(rgba(148, 163, 184, 0.12), rgba(148, 163, 184, 0.12)) 0 58px / 84% 10px no-repeat,
        linear-gradient(rgba(148, 163, 184, 0.12), rgba(148, 163, 184, 0.12)) 0 calc(100% - 56px) / 100% 56px no-repeat;
}

.chart-body .loading-text::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(90deg,
            transparent 0%,
            rgba(255, 255, 255, 0.06) 42%,
            rgba(255, 255, 255, 0.18) 52%,
            transparent 100%);
    animation: admin-skeleton-shimmer 1.35s ease-in-out infinite;
}

/* ---- Heatmap Legend ---- */
.heatmap-legend {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    margin-top: 12px;
    padding-top: 12px;
    border-top: 1px solid var(--card-border);
}

.legend-label {
    font-size: 0.75rem;
    color: var(--text-secondary);
}

.legend-gradient {
    width: 120px;
    height: 12px;
    border-radius: 6px;
    background: linear-gradient(to right, #ebedf0, #9be9a8, #40c463, #30a14e, #216e39);
}

/* ============================================
   MOBILE LAYOUT FIXES
   ============================================ */

@media (max-width: 768px) {

    /* Fix Permissions Switch Cutoff & Consistency */
    /* Force single row layout for consistent alignment */
    .admin-control-header {
        flex-wrap: nowrap !important;
        height: auto !important;
        min-height: 40px;
        padding-right: 12px !important;
        justify-content: space-between !important;
        align-items: center !important;
    }

    /* Target the right-side control (Badge or Switch) */
    .admin-switch-reset,
    .admin-control-header .super-admin-badge {
        margin-right: 0 !important;
        /* Reset any negative margins */
        margin-top: 0 !important;
        margin-bottom: 0 !important;
        flex-shrink: 0;
        order: 0 !important;
        /* Reset order to stay on right */

        /* Reset transform specific to mobile to ensure touch target and alignment */
        transform: none !important;
    }

    /* Fix stretched switch: Restore block layout and fixed dimensions */
    .admin-switch-reset {
        display: inline-block !important;
        /* NOT flex, because children are absolute */
        width: 40px !important;
        height: 22px !important;
        vertical-align: middle;
    }

    /* Ensure title doesn't push switch out if text is long */
    .admin-control-left {
        flex: 1;
        min-width: 0;
        margin-right: 8px;
    }

    /* Fix Permissions Panel Cutoff & Squeeze */
    /* Fix Permissions Panel Cutoff & Squeeze */
    .modal-permissions-panel {
        /* display: block !important;  <-- REMOVED to allow JS toggle (display: none) to work */
        width: 100% !important;
        min-width: 100% !important;
        box-sizing: border-box !important;
        padding: 12px !important;
        margin: 12px 0 0 0 !important;
        /* Top margin only */
        overflow-x: hidden;
        clear: both;
        float: none;
    }

    /* Ensure parent container allows full width */
    .info-block {
        display: block !important;
        width: 100% !important;
    }

    /* REORDERING: Move Permissions below User Card */
    .user-modal-left {
        display: flex !important;
        flex-direction: column !important;
    }

    .user-modal-left .user-card {
        order: -2 !important;
        /* Always top */
    }

    /* Others */
    .user-modal-left .permissions-block {
        order: -1 !important;
        margin-top: 12px !important;
    }

    /* FIX: Reduce padding to prevent narrow cutoff and gain space */
    .user-modal-left {
        padding: 16px 12px 28px !important;
        /* Reduced from 24px 20px */
        width: 100% !important;
        box-sizing: border-box !important;
    }

    /* FIX: Ensure permissions panel fits inside */
    .modal-permissions-panel {
        width: auto !important;
        /* Allow it to fit naturally */
        margin-left: 0 !important;
        margin-right: 0 !important;
        padding: 12px !important;
        box-sizing: border-box !important;
    }

    /* FIX: Ensure save button doesn't overflow */
    .perm-save-btn {
        width: 100% !important;
        box-sizing: border-box !important;
        margin-left: 0 !important;
        margin-right: 0 !important;
    }

    /* Other blocks (Assets, Tags) will default to order 0 and appear below */
}




[data-theme="dark"] .legend-gradient {
