    font-size: 0.8rem;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-sm.btn-secondary {
    background: transparent;
    border: 1px solid var(--card-border);
    color: var(--text-secondary);
}

.btn-sm.btn-secondary:hover {
    background: var(--bg-secondary);
    color: var(--text-main);
}

.btn-icon-sm {
    background: transparent;
    border: none;
    color: var(--text-secondary);
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
}

.btn-icon-sm:hover {
    color: #ef4444;
    background: rgba(239, 68, 68, 0.1);
}

.form-actions {
    display: flex;
    gap: 12px;
    justify-content: flex-end;
    margin-top: 20px;
}

.header-actions {
