    gap: 8px;
}

.btn-sm.btn-primary {
    background: var(--accent-starry, #6b9ece);
    border: none;
    color: #fff;
}

.btn-sm.btn-primary:hover {
    filter: brightness(1.1);
}

/* ---- Analytics Toolbar (Premium) ---- */
.analytics-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 24px;
    padding: 12px 16px;
    margin-bottom: 20px;
    background: var(--bg-secondary);
    border-radius: 14px;
    border: 1px solid var(--card-border);
    position: relative;
}

.toolbar-left,
.toolbar-right {
    display: flex;
    align-items: center;
    gap: 12px;
}

.analytics-toolbar .toolbar-center {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 12px;
}

/* Segment Control */
.segment-control {
    display: flex;
    position: relative;
    background: rgba(0, 0, 0, 0.06);
    border-radius: 10px;
    padding: 3px;
}

.segment-btn {
    position: relative;
    z-index: 1;
    padding: 8px 16px;
    background: transparent;
    border: none;
    border-radius: 8px;
    color: var(--text-secondary);
    font-size: 0.85rem;
    font-weight: 500;
    cursor: pointer;
    transition: color 0.2s;
}

.segment-btn:hover {
    color: var(--text-main);
}

.segment-btn.active {
    color: var(--accent-starry);
}

.segment-indicator {
    position: absolute;
    top: 3px;
    left: 3px;
    width: calc(25% - 1.5px);
    height: calc(100% - 6px);
    background: #fff;
    border-radius: 8px;
