/* Small Toggle Switch for Toolbar */
.toggle-switch-sm {
    position: relative;
    display: inline-block;
    width: 36px;
    height: 20px;
}

.toggle-switch-sm input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-switch-sm .toggle-slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(100, 116, 139, 0.4);
    transition: 0.3s;
    border-radius: 20px;
}

.toggle-switch-sm .toggle-slider:before {
    position: absolute;
    content: "";
    height: 14px;
    width: 14px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.toggle-switch-sm input:checked+.toggle-slider {
    background-color: var(--accent-starry);
}

.toggle-switch-sm input:checked+.toggle-slider:before {
    transform: translateX(16px);
}

