.toggle-switch {
    position: relative;
    display: inline-block;
    width: 40px;
    height: 22px;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 22px;
    transition: 0.3s;
}

/* Light Mode Toggle Track Visibility */
:root:not([data-theme="dark"]) .toggle-slider {
    background: #e2e8f0;
    /* Visible grey track on white bg */
}


.toggle-slider::before {
    content: '';
    position: absolute;
    width: 16px;
    height: 16px;
    left: 3px;
    bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: 0.3s;
}

.toggle-switch input:checked+.toggle-slider {
    background: var(--accent-starry, #6b9ece);
    /* Fallback to hex if var missing in light mode */
}

/* Ensure Light Mode Active State is Blue */
:root:not([data-theme="dark"]) .toggle-switch input:checked+.toggle-slider {
    background: #6b9ece;
}


.toggle-switch input:checked+.toggle-slider::before {
    transform: translateX(18px);
}

