/* ANALYTICS TABS SYSTEM */
/* ============================================ */

.analytics-tabs {
    border-bottom: none !important;
    gap: 12px;
}

.analytics-tabs .admin-tab {
    background: transparent;
    border: 1px solid transparent;
    border-radius: 8px;
    padding: 8px 16px;
    font-size: 0.9rem;
    color: var(--text-secondary);
    transition: all 0.2s;
}

.analytics-tabs .admin-tab:hover {
    background: rgba(107, 158, 206, 0.1);
    color: var(--text-main);
}

.analytics-tabs .admin-tab.active {
    background: var(--bg-secondary);
    border-color: var(--card-border);
    color: var(--accent-starry);
    font-weight: 600;
}

#analyticsTabsNav.analytics-center-tabs {
    justify-content: center;
    align-items: center;
    gap: 28px;
    flex-wrap: nowrap;
    overflow-x: auto;
    overflow-y: hidden;
    margin: 0 0 24px;
    padding: 0 6px 16px;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
}

#analyticsTabsNav.analytics-center-tabs::-webkit-scrollbar {
    display: none;
}

#analyticsTabsNav .admin-tab-indicator {
    display: none;
}

#analyticsTabsNav .analytics-tab-group {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 26px;
    flex: 0 0 auto;
    flex-wrap: nowrap;
}

#analyticsTabsNav .analytics-tab-group__tabs {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 24px;
    flex: 0 0 auto;
    flex-wrap: nowrap;
}

#analyticsTabsNav .analytics-tab-group__label {
    display: none;
}

#analyticsTabsNav .analytics-tab-group__label,
#analyticsTabsNav .admin-tab {
    position: relative;
    flex: 0 0 auto;
    padding: 0 4px 15px;
    border: none;
    border-radius: 0;
    background: transparent;
    color: rgba(255, 255, 255, 0.52);
    font-family: var(--font-sans);
    font-size: 0.98rem;
    line-height: 1.15;
    font-weight: 700;
    letter-spacing: 0.01em;
    white-space: nowrap;
    cursor: pointer;
    appearance: none;
    transition: color 0.2s ease, transform 0.2s ease;
}

#analyticsTabsNav .analytics-tab-group__label {
    font-size: 1.02rem;
}

#analyticsTabsNav .analytics-tab-group__label:hover,
#analyticsTabsNav .analytics-tab-group__label:focus-visible,
#analyticsTabsNav .admin-tab:hover:not(.active),
#analyticsTabsNav .admin-tab:focus-visible {
    color: rgba(255, 255, 255, 0.82);
    transform: translateY(-1px);
    outline: none;
}

#analyticsTabsNav .analytics-tab-group__label::after,
#analyticsTabsNav .admin-tab::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: -1px;
    height: 3px;
    border-radius: 999px;
    background: linear-gradient(90deg, rgba(133, 186, 255, 0.92), rgba(107, 158, 206, 0.85));
    opacity: 0;
    transform: scaleX(0.4);
    transform-origin: center;
    transition: opacity 0.2s ease, transform 0.2s ease;
}

#analyticsTabsNav .analytics-tab-group__label.active,
#analyticsTabsNav .admin-tab.active {
    color: #f8fafc;
    transform: none;
}

#analyticsTabsNav .analytics-tab-group__label.active::after,
#analyticsTabsNav .admin-tab.active::after {
    opacity: 1;
    transform: scaleX(1);
}

