.settings-section {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 16px;
    max-width: 600px;
}

.settings-section--compact {
    max-width: 100%;
}

.settings-section h3 {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 16px;
    font-size: 1rem;
    color: var(--text-main);
}

.settings-section h3 i {
    color: var(--accent-starry);
}

.settings-section__intro {
    margin: -4px 0 0;
    color: var(--text-secondary);
    font-size: 0.84rem;
    line-height: 1.6;
}

/* Locked Accounts Badge */
.locked-count-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 22px;
    height: 22px;
    padding: 0 6px;
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
    font-size: 0.75rem;
    font-weight: 600;
    border-radius: 11px;
    margin-left: 8px;
}

.locked-count-badge:empty,
.locked-count-badge[hidden],
#unlockAllBtn[hidden],
#noLockedAccountsMsg[hidden] {
    display: none;
}

/* Locked Accounts Container */
.locked-accounts-container {
    margin-top: 8px;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.locked-accounts-list {
    max-height: 280px;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--accent-starry) transparent;
    padding-right: 4px;
}

.locked-accounts-list::-webkit-scrollbar {
    width: 4px;
}

.locked-accounts-list::-webkit-scrollbar-thumb {
    background: var(--accent-starry);
    border-radius: 4px;
}

/* Empty State */
.locked-accounts-list .empty-state {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 18px 0 12px;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.locked-accounts-list .empty-state i {
    font-size: 1.2rem;
    color: #22c55e;
}

/* Locked Account Item */
.locked-account-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 14px;
    background: rgba(239, 68, 68, 0.05);
    border: 1px solid rgba(239, 68, 68, 0.15);
    border-radius: 10px;
    margin-bottom: 8px;
    transition: all 0.2s;
}

.locked-account-item:last-child {
    margin-bottom: 0;
}

.locked-account-item:hover {
    background: rgba(239, 68, 68, 0.08);
    border-color: rgba(239, 68, 68, 0.25);
}

.locked-account-info {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;
    flex: 1 1 auto;
}

.locked-account-email {
    font-weight: 500;
    color: var(--text-main);
    font-size: 0.9rem;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.locked-account-meta {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 0.8rem;
    color: var(--text-secondary);
    flex-wrap: wrap;
}

.locked-account-meta .attempts {
    color: #ef4444;
}

.locked-account-meta .expires {
    display: flex;
    align-items: center;
    gap: 4px;
}

.locked-account-meta .expires i {
    font-size: 0.7rem;
}

/* Unlock Button */
.btn-unlock {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    background: transparent;
    border: 1px solid rgba(34, 197, 94, 0.4);
    border-radius: 6px;
    color: #22c55e;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.2s;
    flex: 0 0 auto;
    white-space: nowrap;
}

.btn-unlock:hover {
    background: rgba(34, 197, 94, 0.15);
    border-color: #22c55e;
}

.btn-unlock i {
    font-size: 0.75rem;
}

/* Button Variants */
.btn-sm.btn-secondary {
    background: var(--bg-secondary);
    border: 1px solid var(--card-border);
    color: var(--text-main);
}

.btn-sm.btn-secondary:hover {
    background: rgba(107, 158, 206, 0.1);
    border-color: var(--accent-starry);
}

.btn-sm.btn-warning {
    background: rgba(239, 68, 68, 0.1);
    border: 1px solid rgba(239, 68, 68, 0.3);
    color: #ef4444;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.btn-sm.btn-warning:hover {
    background: rgba(239, 68, 68, 0.2);
    border-color: #ef4444;
}

/* Config Item Row for Settings */
.config-item-row {
