/* Export Buttons Grid */
.export-buttons-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 12px;
}

.export-btn {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    padding: 20px 16px;
    background: var(--bg-main);
    border: 1px solid var(--card-border);
    border-radius: 12px;
    color: var(--text-main);
    cursor: pointer;
    transition: all 0.2s;
}

.export-btn:hover {
    background: var(--bg-secondary);
    border-color: var(--accent-starry);
    transform: translateY(-2px);
}

.export-btn i {
    font-size: 1.5rem;
    color: var(--accent-starry);
}

.export-btn span {
    font-weight: 500;
}

.export-btn small {
    color: var(--text-secondary);
    font-size: 0.8rem;
}

/* Export View Specific Styles */
#settings-view-export .module-content {
    display: flex;
    justify-content: center;
}

#settings-view-export .settings-section {
    max-width: 500px;
    width: 100%;
}

#settings-view-export .export-buttons-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
}

@media (max-width: 768px) {
    #settings-view-export .export-buttons-grid {
        grid-template-columns: 1fr;
        /* Stack vertically on mobile */
        gap: 12px;
    }

    #settings-view-export .settings-section {
