        padding: 16px;
        /* Reduce padding from 20px */
        box-sizing: border-box;
    }

    #settings-view-export .module-content {
        padding: 12px;
        /* Reduce container padding */
        display: block;
        /* Remove flex centering to verify normal flow */
    }
}



/* Config Table */
.config-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 12px;
    table-layout: fixed;
}

.config-table th,
.config-table td {
    padding: 10px 12px;
    text-align: left;
    border-bottom: 1px solid var(--card-border);
}

/* Column widths */
.config-table th:first-child,
.config-table td:first-child {
    width: 30%;
    min-width: 100px;
}

.config-table th:nth-child(2),
.config-table td:nth-child(2),
.config-table th:nth-child(3),
.config-table td:nth-child(3),
.config-table th:nth-child(4),
.config-table td:nth-child(4) {
    width: 15%;
}

.config-table th:nth-child(5),
.config-table td:nth-child(5) {
    width: 10%;
}

.config-table th:last-child,
.config-table td:last-child {
    width: 40px;
}

.config-table th {
    font-size: 0.8rem;
    color: var(--text-secondary);
    font-weight: 500;
    text-transform: uppercase;
}

.config-table td input {
    width: 100%;
    padding: 6px 10px;
    border: 1px solid transparent;
    border-radius: 6px;
    background: transparent;
    color: var(--text-main);
    transition: all 0.2s;
}

.config-table td input[type="text"] {
    text-overflow: ellipsis;
}

.config-table td input:focus {
    background: var(--bg-main);
    border-color: var(--accent-starry);
    outline: none;
}

.status-toggle {
    width: 40px;
    height: 22px;
    background: rgba(100, 116, 139, 0.4);
    border-radius: 11px;
    position: relative;
    cursor: pointer;
    transition: background 0.3s, transform 0.15s;
    flex: 0 0 auto;
    display: inline-block;
}

.status-toggle.status-toggle--pulse {
    animation: admin-config-toggle-pulse 0.16s ease-out;
}

.status-toggle.active {
    background: #22c55e;
}

.status-toggle::after {
    content: '';
    position: absolute;
    width: 18px;
    height: 18px;
    background: rgba(255, 255, 255, 0.85);
    border-radius: 50%;
    top: 2px;
    left: 2px;
    transition: transform 0.3s;
}

.status-toggle.active::after {
    transform: translateX(18px);
    background: white;
}

@keyframes admin-config-toggle-pulse {
    0% {
        transform: scale(1);
    }

    100% {
        transform: scale(1.1);
    }
}

.config-table .btn-delete {
    padding: 6px;
    background: none;
    border: none;
    color: var(--text-secondary);
    cursor: pointer;
    border-radius: 6px;
    transition: all 0.2s;
}

.config-table .btn-delete:hover {
    background: rgba(239, 68, 68, 0.1);
    color: #ef4444;
}

/* Add Button */
.btn-add-config {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    background: rgba(107, 158, 206, 0.1);
    border: 1px dashed var(--accent-starry);
    border-radius: 8px;
    color: var(--accent-starry);
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-add-config:hover {
    background: rgba(107, 158, 206, 0.2);
    transform: translateY(-1px);
}

/* Channel Tags */
.channel-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 12px;
}

.channel-tag {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 12px;
    background: var(--bg-secondary);
    border: 1px solid var(--card-border);
    border-radius: 20px;
    font-size: 0.85rem;
    color: var(--text-main);
    transition: all 0.2s;
    animation: slideIn 0.3s ease;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.channel-tag .remove-tag {
    width: 16px;
    height: 16px;
    background: rgba(239, 68, 68, 0.1);
    border: none;
    border-radius: 50%;
    color: #ef4444;
    font-size: 10px;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
}

.channel-tag .remove-tag:hover {
    background: #ef4444;
    color: white;
}

.channel-tag.default {
    border-color: var(--accent-starry);
    background: rgba(107, 158, 206, 0.1);
}

.add-channel-row {
    display: flex;
    gap: 8px;
}

.add-channel-row input {
    flex: 1;
    padding: 8px 12px;
    border: 1px solid var(--card-border);
    border-radius: 8px;
    background: var(--bg-main);
    color: var(--text-main);
}

.add-channel-row input:focus {
    outline: none;
    border-color: var(--accent-starry);
}

